import type { DrizzleDB } from "../db";
import type { scoreType } from "../db/schema/league-schema";
import * as matchRepository from "../repositories/match-repository";
import * as seasonPlayerRepository from "../repositories/season-player-repository";

export type SeasonScoreType = (typeof scoreType)[number];

export type Standing = Awaited<ReturnType<typeof seasonPlayerRepository.getStanding>>;

export interface MatchDisplayPlayer {
	id: string;
	name: string;
	image: string | null;
	teamName: string | null;
	teamLogo: string | null;
	homeTeam: boolean;
}

export interface MatchInsertData {
	match: {
		id: string;
		seasonId: string;
		homeScore: number;
		awayScore: number;
		createdAt: Date;
	};
	scoreType: SeasonScoreType;
	players: MatchDisplayPlayer[];
	standings: Standing;
}

export async function buildMatchInsertData(
	db: DrizzleDB,
	opts: {
		match: MatchInsertData["match"];
		scoreType: SeasonScoreType;
		standings: Standing;
	}
): Promise<MatchInsertData> {
	const matchWithPlayers = await matchRepository.getMatchWithPlayers({ db, matchId: opts.match.id });
	return {
		match: opts.match,
		scoreType: opts.scoreType,
		players: matchWithPlayers?.players ?? [],
		standings: opts.standings,
	};
}
```

**Step 4: Wire into `apps/worker/src/trpc/router/match-router.ts`**

4a. Add import after the existing `import type { AchievementQueueMessage } ...` line:
```ts
import { buildMatchInsertData, type SeasonScoreType } from "../../services/match-events";
```

4b. Replace `finalizeMatchCreation` entirely. Its current signature has `createdMatch: { id: string };` and `seasonPlayerIds: string[];`, and its body broadcasts `match:insert` with `data: { match: createdMatch, standings }`, then checks streaks, then sends `ACHIEVEMENT_QUEUE.send({ seasonPlayerIds, leagueSlug, seasonSlug })`, and returns `createdMatch`. Replace it with:

```ts
async function finalizeMatchCreation({
	ctx,
	seasonSlug,
	seasonId,
	createdMatch,
	seasonPlayerIds,
	scoreType,
}: {
	ctx: {
		db: Parameters<typeof seasonPlayerRepository.getStanding>[0]["db"];
		env: Pick<Env, "SEASON_SSE" | "ACHIEVEMENT_QUEUE">;
		waitUntil: (promise: Promise<unknown>) => void;
		organization: { slug: string };
		authentication: { user: { id: string; name: string } };
	};
	seasonSlug: string;
	seasonId: string;
	createdMatch: {
		id: string;
		seasonId: string;
		homeScore: number;
		awayScore: number;
		createdAt: Date;
	};
	seasonPlayerIds: string[];
	scoreType: SeasonScoreType;
}) {
	const standings = await seasonPlayerRepository.getStanding({
		db: ctx.db,
		seasonId,
	});

	const data = await buildMatchInsertData(ctx.db, {
		match: createdMatch,
		scoreType,
		standings,
	});

	ctx.waitUntil(
		broadcastSeasonEvent(ctx.env, ctx.organization.slug, seasonSlug, {
			type: "match:insert",
			data,
			user: {
				id: ctx.authentication.user.id,
				name: ctx.authentication.user.name,
			},
		})
	);

	const [streakPlayers, streakTeams] = await Promise.all([
		matchRepository.checkStreakThresholds({
			db: ctx.db,
			seasonPlayerIds,
		}),
		matchRepository.checkTeamStreakThresholds({
			db: ctx.db,
			matchId: createdMatch.id,
		}),
	]);

	broadcastStreakEvents(
		ctx.waitUntil.bind(ctx),
		ctx.env,
		ctx.organization.slug,
		seasonSlug,
		streakPlayers,
		streakTeams,
		{
			id: ctx.authentication.user.id,
			name: ctx.authentication.user.name,
		}
	);

	await ctx.env.ACHIEVEMENT_QUEUE.send({
		seasonPlayerIds,
		leagueSlug: ctx.organization.slug,
		seasonSlug,
	} satisfies AchievementQueueMessage);

	return createdMatch;
}
```

4c. Refactor `createFromFixture` to reuse `finalizeMatchCreation`. Currently, after creating the match and calling `assignMatchToFixture`, it has a long inline block: it computes `standings`, broadcasts `match:insert`, checks streaks (`checkStreakThresholds`/`checkTeamStreakThresholds`), calls `broadcastStreakEvents`, sends the achievement queue, and `return createdMatch;`. Replace that ENTIRE inline block (from `const standings = await seasonPlayerRepository.getStanding({...})` through `return createdMatch;`) with a single call:

